-- Rollback of daily-bank-2026-11-lot2.sql: removes the rows of this lot that were not
-- published yet (a published row is already a live quiz page; it stays). Kpop rows only.
delete from public.quiz_bank qb
where title in ('ZEROBASEONE: From Boys Planet to In Bloom', 'K-pop Agency Founders', 'LE SSERAFIM: The EASY to HOT Era', 'K-pop Songs About Magic', 'TREASURE True or False', 'DAY6: From Congratulations to Fourever', 'TXT: From Sugar Rush Ride to Deja Vu', 'K-pop Songs of 2025', 'KPop Demon Hunters Quiz', 'BOYNEXTDOOR: From WHO! to No Genre', 'K-pop Award Shows True or False', 'IVE: The SWITCH to EMPATHY Era', 'K-pop Groups and Their First Wins', 'NMIXX: From O.O to Blue Valentine', 'K-pop Songs With Numbers', 'ATEEZ: The Golden Hour Era', 'Wonder Girls True or False', 'Red Velvet: From Happiness to Cosmic', 'K-pop Groups That Debuted in 2025', 'K-pop Winter and Christmas Songs') and status in ('verified', 'scheduled') and published_quiz_id is null and coalesce(to_jsonb(qb) ->> 'site_id', 'kpop') = 'kpop';
